/**
 * 负责梦魇私有状态、既有字段校验、目标政策与玩家投影；输入是原角色和候选上下文。
 * 输出为新状态、合法目标或原可读状态引用；玩家投影另复制历史中的 day／targetId。
 * 不执行恐惧阶段或序列化运行授权；历史顺序、已付款状态与当前许可分别保留。
 */
import type {
  FearActionPolicy,
  NightmareWolfActionPolicy,
  NightmareShadowState,
  NightmareShadowReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, type EntityId } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";

export const NIGHTMARE_SHADOW_ROLE = "nightmare" as const;
export const NIGHTMARE_SHADOW_POLICY = "awa_nightmare_dreamer_v1" as const;
function data(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function freshNightmareShadowState(
  fearActionPolicy: FearActionPolicy = "optional",
  wolfActionPolicy: NightmareWolfActionPolicy = "standard",
): NightmareShadowState {
  return {
    policy: NIGHTMARE_SHADOW_POLICY,
    fearActionPolicy,
    wolfActionPolicy,
    packReady: false,
    lastDay: null,
    lastTarget: null,
    history: [],
  };
}
function validId(value: unknown): value is EntityId {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}
function validDay(value: unknown): value is number {
  return validId(value);
}
export function getNightmareShadowState(
  role: RoleComponent | undefined,
): NightmareShadowReadState | undefined {
  if (data(role, "role") !== NIGHTMARE_SHADOW_ROLE || data(role, "camp") !== Camp.Wolf)
    return undefined;
  const state = data(data(role, "privateState"), "nightmareShadow");
  const fear = data(state, "fearActionPolicy"),
    wolf = data(state, "wolfActionPolicy");
  const day = data(state, "lastDay"),
    target = data(state, "lastTarget");
  const history = data(state, "history"),
    ready = data(state, "packReady");
  if (
    data(state, "policy") !== NIGHTMARE_SHADOW_POLICY ||
    (fear !== "optional" && fear !== "required_when_legal") ||
    (wolf !== "standard" && wolf !== "no_blast_no_self_knife") ||
    typeof ready !== "boolean" ||
    (day !== null && !validDay(day)) ||
    (target !== null && !validId(target)) ||
    (history !== null && typeof history === "object" && types.isProxy(history)) ||
    !Array.isArray(history)
  )
    return undefined;
  const length = data(history, "length");
  if (typeof length !== "number") return undefined;
  if (day === null)
    return !ready && target === null && length === 0
      ? (state as NightmareShadowReadState)
      : undefined;
  if (!ready || length === 0) return undefined;
  let previous = 0;
  for (let i = 0; i < length; i++) {
    const entry = data(history, String(i));
    const entryDay = data(entry, "day"),
      entryTarget = data(entry, "targetId");
    if (
      !validDay(entryDay) ||
      entryDay <= previous ||
      (entryTarget !== null && !validId(entryTarget))
    )
      return undefined;
    previous = entryDay;
    if (i === length - 1 && (entryDay !== day || entryTarget !== target)) return undefined;
  }
  return state as NightmareShadowReadState;
}
/** 请求、校验、基线策略与目标提示使用同一目标政策，避免相邻两夜的禁选规则漂移。 */
export function nightmareFearTargets(world: World, actorId: EntityId, day: number): EntityId[] {
  const state = getNightmareShadowState(world.getComponent(actorId, COMPONENT.Role));
  if (
    !state ||
    !validDay(day) ||
    !world.getAliveEntityIds().includes(actorId) ||
    (day > 1 && !state.packReady) ||
    (state.lastDay !== null && day <= state.lastDay)
  )
    return [];
  return world.getAliveEntityIds().filter((id) => {
    if (id === actorId || (state.lastDay === day - 1 && state.lastTarget === id)) return false;
    const target = world.getComponent(id, COMPONENT.Role);
    return !!target && (!state.packReady || target.camp !== Camp.Wolf);
  });
}

/** 按原顺序复制玩家字段及每条历史；不返回运行状态或复用 history／entry 对象。 */
export function projectNightmareShadowState(
  role: RoleComponent | undefined,
): NightmareShadowState | undefined {
  const nightmare = getNightmareShadowState(role);
  if (nightmare) {
    const history: Array<{ day: number; targetId: number | null }> = [];
    for (let i = 0; i < nightmare.history.length; i++) {
      const entry = nightmare.history[i]!;
      history.push({ day: entry.day, targetId: entry.targetId });
    }
    return {
      policy: nightmare.policy,
      fearActionPolicy: nightmare.fearActionPolicy,
      wolfActionPolicy: nightmare.wolfActionPolicy,
      packReady: nightmare.packReady,
      lastDay: nightmare.lastDay,
      lastTarget: nightmare.lastTarget,
      history,
    };
  }
}

/**
 * Owns Nightmare roster and fear bindings for one actual night. Inputs are original native roles
 * and the accepted fear choice; outputs are current fear/knife blocking predicates and recorded
 * choice state. Only the bound roster participates; a replaced component cannot silently reopen
 * the night.
 */
import type {
  NightmareShadowState,
  NightmareShadowReadState,
} from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeVersion,
  aliveLifeDescriptor,
  type AliveComponent,
} from "../../../../core/domain/components/alive";

import type { World } from "../../../../core/domain/world";
import { Camp, type EntityId } from "../../../../core/domain/identity";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { NightAbilityReadView } from "../abilities";
import { getNightmareShadowState, nightmareFearTargets } from "./state";

function stateIdentity(state: NightmareShadowReadState): string {
  const history: Array<[number, EntityId | null]> = [];
  for (let i = 0; i < state.history.length; i++) {
    const entry = state.history[i]!;
    history.push([entry.day, entry.targetId]);
  }
  return JSON.stringify([
    state.policy,
    state.fearActionPolicy,
    state.wolfActionPolicy,
    state.packReady,
    state.lastDay,
    state.lastTarget,
    history,
  ]);
}
function authority(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    ability.disabled,
    ability.deathExpired,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
function captureRole(world: World, id: EntityId) {
  const role = world.getComponent(id, COMPONENT.Role);
  if (!role) throw new Error("nightmare_roster_missing");
  const kind = role.role,
    camp = role.camp,
    privateState = role.privateState;
  const life = world.getComponent(id, COMPONENT.Alive);
  const descriptor = life && aliveLifeDescriptor(life);
  const version = life && aliveLifeVersion(life);
  if (!life || !descriptor || version === undefined)
    throw new Error("nightmare_roster_life_missing");
  const lifeCurrent = () => {
    const current = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      world.getComponent(id, COMPONENT.Alive) === life &&
      current?.get === descriptor.get &&
      current?.set === descriptor.set &&
      (aliveLifeVersion(life) === version ||
        (aliveLifeVersion(life) === version + 1 && !life.alive))
    );
  };
  const refs = Object.entries(privateState);
  const slots = Object.entries((privateState as { readonly abilities?: unknown }).abilities ?? {});
  const abilities = Object.values(
    ((privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
      string,
      NightAbilityReadView
    >,
  ).map((ability) => ({
    ability,
    state: ability.state,
    source: ability.source,
    identity: authority(ability),
  }));
  return {
    id,
    role,
    current: () =>
      lifeCurrent() &&
      world.getComponent(id, COMPONENT.Role) === role &&
      role.role === kind &&
      role.camp === camp &&
      role.privateState === privateState &&
      refs.every(
        ([key, value]) => (privateState as Readonly<Record<string, unknown>>)[key] === value,
      ) &&
      Object.keys((privateState as { readonly abilities?: unknown }).abilities ?? {}).length ===
        slots.length &&
      slots.every(
        ([key, value]) =>
          (
            (privateState as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] === value,
      ) &&
      abilities.every(
        (a) =>
          a.ability.state === a.state &&
          a.ability.source === a.source &&
          authority(a.ability) === a.identity,
      ),
  };
}
type Board = {
  actorId: EntityId;
  state: NightmareShadowReadState;
  expectedState: string;
  roster: ReturnType<typeof captureRole>[];
  night: {
    day: number;
    required: boolean;
    committed: boolean;
    target: NightLifeScope | null;
    wolfBlocked: boolean;
  } | null;
};
const boards = new WeakMap<World, Board>();
export function installNightmareBoard(world: World): void {
  if (boards.has(world)) throw new Error("nightmare_board_reinstall");
  const roster = world.entityIds().map((id) => captureRole(world, id));
  const actors = roster.filter((row) => getNightmareShadowState(row.role));
  if (actors.length !== 1) throw new Error("nightmare_actor_count");
  const state = getNightmareShadowState(actors[0].role)!;
  boards.set(world, {
    actorId: actors[0].id,
    state,
    expectedState: stateIdentity(state),
    roster,
    night: null,
  });
}
export function isNightmareBoard(world: World): boolean {
  return boards.has(world);
}
export function assertNightmareRosterCurrent(world: World): void {
  const board = boards.get(world);
  if (!board) return;
  if (
    world.entityIds().length !== board.roster.length ||
    board.roster.some((row) => !row.current()) ||
    getNightmareShadowState(world.getComponent(board.actorId, COMPONENT.Role)) !== board.state ||
    stateIdentity(board.state) !== board.expectedState
  )
    throw new Error("nightmare_roster_revoked");
}
export function beginNightmareNight(world: World, day: number): EntityId | null {
  const board = boards.get(world);
  if (!board) return null;
  assertNightmareRosterCurrent(world);
  if (
    !Number.isSafeInteger(day) ||
    day !== (board.night?.day ?? 0) + 1 ||
    (board.night?.required && !board.night.committed)
  )
    throw new Error("nightmare_night_reentry");
  board.night = {
    day,
    required: world.getAliveEntityIds().includes(board.actorId),
    committed: false,
    target: null,
    wolfBlocked: false,
  };
  return world.getAliveEntityIds().includes(board.actorId) ? board.actorId : null;
}
export function nightmarePackReady(world: World): boolean {
  assertNightmareRosterCurrent(world);
  return boards.get(world)?.state.packReady ?? true;
}
export function commitNightmareFear(
  world: World,
  actorId: EntityId,
  day: number,
  targetId: EntityId | null,
): void {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  if (
    !board ||
    !night ||
    board.actorId !== actorId ||
    night.day !== day ||
    night.committed ||
    !world.getAliveEntityIds().includes(actorId)
  )
    throw new Error("nightmare_fear_scope_invalid");
  const candidates = nightmareFearTargets(world, actorId, day);
  if (
    targetId === null
      ? board.state.fearActionPolicy === "required_when_legal" && candidates.length > 0
      : !candidates.includes(targetId)
  )
    throw new Error("nightmare_fear_target_invalid");
  const target = targetId === null ? null : captureNightLife(world, targetId);
  if (targetId !== null && !target) throw new Error("nightmare_fear_target_invalid");
  const wolfBlocked =
    targetId !== null && world.getComponent(targetId, COMPONENT.Role)?.camp === Camp.Wolf;
  (board.state as Pick<NightmareShadowState, "lastDay">).lastDay = day;
  (board.state as Pick<NightmareShadowState, "lastTarget">).lastTarget = targetId;
  (board.state as Pick<NightmareShadowState, "packReady">).packReady = true;
  Array.prototype.push.call(board.state.history, { day, targetId });
  board.expectedState = stateIdentity(board.state);
  night.committed = true;
  night.target = target;
  night.wolfBlocked = wolfBlocked;
}
/** Normal first death preserves this night's silence for the death-action window. */
export function nightmareFearBlocks(
  world: World,
  id: EntityId,
  day: number,
  allowFirstDeath = false,
): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night,
    target = night?.target;
  if (!night || night.day !== day || !target || target.id !== id) return false;
  if (livingNightLife(world, target)) return true;
  if (!allowFirstDeath) throw new Error("nightmare_target_life_revoked");
  return (
    world.getComponent(id, COMPONENT.Alive) === target.life &&
    !target.life.alive &&
    aliveLifeVersion(target.life) === target.version + 1
  );
}
export function nightmareKnifeBlocked(world: World, day?: number): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night;
  return !!night && (day === undefined || night.day === day) && night.wolfBlocked;
}

export function nightmareFearPending(world: World, actorId: EntityId, day: number): boolean {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  return (
    !!board &&
    !!night &&
    board.actorId === actorId &&
    night.day === day &&
    night.required &&
    !night.committed &&
    world.getAliveEntityIds().includes(actorId)
  );
}

/**
 * 负责 噩梦之影 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import {
  NIGHTMARE_SHADOW_POLICY,
  freshNightmareShadowState,
  getNightmareShadowState,
  nightmareFearTargets,
} from "./state";
import { NIGHTMARE_FEAR_STAGE } from "./night_stages";
import { nightmarePackReady, nightmareFearPending } from "./night_frame";
const parameters = z.strictObject({
  policy: z.literal(NIGHTMARE_SHADOW_POLICY).default(NIGHTMARE_SHADOW_POLICY),
  fearActionPolicy: z.enum(["optional", "required_when_legal"]).default("optional"),
  wolfActionPolicy: z.enum(["standard", "no_blast_no_self_knife"]).default("standard"),
});
export const NIGHTMARE_SHADOW_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.NightmareShadow,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.NightmareShadow,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Dreamer,
    ],
    label: roleName("nightmare"),
    skillBrief: text("zh-CN", "role.nightmare.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: (role) => getNightmareShadowState(role)?.wolfActionPolicy === "standard",
    wolfTeam: (role, world) => {
      const ready =
        !!getNightmareShadowState(role)?.packReady && (!world || nightmarePackReady(world));
      return {
        recognizedByPack: ready,
        recognizes: ready ? "pack" : "none",
        canChat: ready,
        canVoteForKill: ready,
      };
    },
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.nightmareShadow ?? {});
      role.privateState.nightmareShadow = freshNightmareShadowState(
        value.fearActionPolicy,
        value.wolfActionPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, nightmareShadow: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.nightmareShadow ?? {}),
    },
    toolSpecs: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []),
      {
        name: "fear",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["target_id", "abstain"],
          additionalProperties: false,
        },
        argHint: 'fear args: {"target_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.fear.hint",
      },
    ],
    stageDirectives: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "fear",
        messageKey: "action.fear.directive",
        text: text("zh-CN", "action.fear.directive"),
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      fear: ({ world, role, actorId, day, phase, toolCall }) => {
        const state = getNightmareShadowState(role);
        if (
          !state ||
          !nightmareFearPending(world, actorId, day ?? 0) ||
          phase !== Phase.Night ||
          toolCall.name !== "fear" ||
          day === undefined ||
          (state.lastDay !== null && state.lastDay >= day)
        )
          return { code: RuleError.NightmareUnavailable };
        const targets = nightmareFearTargets(world, actorId, day);
        if (toolCall.args.abstain)
          return toolCall.args.target_id === null &&
            (state.fearActionPolicy === "optional" || targets.length === 0)
            ? null
            : { code: RuleError.NightmareTarget };
        return toolCall.args.target_id !== null && targets.includes(toolCall.args.target_id)
          ? null
          : { code: RuleError.NightmareTarget };
      },
    },
    nightStages: [NIGHTMARE_FEAR_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
    baselineAction: (role, request, pick, pickCamp, locale, world) => {
      if (!request.allowedTools.includes("fear"))
        return (
          ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pick,
            pickCamp,
            locale,
            world,
          ) ?? null
        );
      const target = world
        ? (nightmareFearTargets(world, request.actorId, request.context.day)[0] ?? null)
        : null;
      return { name: "fear", args: { target_id: target, abstain: target === null } };
    },
  },
  presentation: nativeRolePresentation("nightmare"),
};

/**
 * 提供梦魇绑定的恐惧资格、普通狼刀目标及原状态读取查询。
 * 输入是玩家／日期、候选序号或原角色；输出保留原恐惧谓词、狼行动政策及同一可读状态绑定。
 * 绑定只捕获原 World 引用，不提前读组件或返回 World、状态写者、夜间开启或效果提交方法。
 * 名单复验与四参数恐惧查询公开同一原函数；死亡窗口仍由调用方明确传入允许首次死亡，不改原撤销；
 * 查询时仍传播原名单撤销与目标生命失败；板子谓词保持原只读绑定及调用方重复参数的读取顺序。
 */
import type { EntityId } from "../../../../core/domain/model";
import { Role } from "../../../../core/domain/identity";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
import { nightmareFearBlocks } from "./night_frame";
export { isNightmareBoard, nightmareKnifeBlocked, assertNightmareRosterCurrent, nightmareFearBlocks } from "./night_frame";
import { getNightmareShadowState } from "./state";

export interface NightmareNightEligibility {
  blocks(actorId: EntityId, day: number): boolean;
}

export function bindNightmareNightEligibility(world: World): NightmareNightEligibility {
  return Object.freeze({
    blocks: (actorId: EntityId, day: number) => nightmareFearBlocks(world, actorId, day),
  });
}

export interface NightmareKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

export function bindNightmareKnifeTargetQuery(world: World): NightmareKnifeTargetQuery {
  return Object.freeze({
    allows: (targetId: EntityId) =>
      world.getComponent(targetId, COMPONENT.Role)?.role !== Role.NightmareShadow ||
      getNightmareShadowState(world.getComponent(targetId, COMPONENT.Role))?.wolfActionPolicy ===
        "standard",
  });
}

export { getNightmareShadowState } from "./state";

/**
 * Runs the Nightmare fear request before affected native night abilities. Inputs are the
 * captured Nightmare frame and validated fear target; outputs are the committed fear choice and
 * event. Blocking predicates remain in the frame and never arise merely from a model refusal.
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getNightmareShadowState } from "./state";
import {
  assertNightmareRosterCurrent,
  beginNightmareNight,
  commitNightmareFear,
} from "./night_frame";

/** First native action: no pack identity may be exposed before this commits. */
export const NIGHTMARE_FEAR_STAGE: NightStageHandler = {
  id: "nightmare_fear",
  priority: 90,
  async execute(ctx) {
    const day = ctx.currentDay();
    const actorId = beginNightmareNight(ctx.world, day);
    if (actorId === null) return;
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getNightmareShadowState(role)) throw new Error("nightmare_fear_actor_invalid");
    const request = ctx.makeRequest(actorId, ["fear"], {
      stage: "nightmare_fear",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
    });
    assertNightmareRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertNightmareRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("nightmare_fear_stale");
    if (action?.name !== "fear") throw new Error("nightmare_fear_action_missing");
    const args = action.args;
    if (
      !args ||
      typeof args.abstain !== "boolean" ||
      (args.abstain
        ? args.target_id !== null
        : typeof args.target_id !== "number" || !Number.isSafeInteger(args.target_id))
    )
      throw new Error("nightmare_fear_action_invalid");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertNightmareRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("nightmare_fear_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "fear")
      throw new Error("nightmare_fear_action_invalid");
    const targetId = validated.sanitizedCall.args.target_id;
    commitNightmareFear(ctx.world, actorId, day, targetId);
    ctx.events.push({
      timestamp: Date.now(),
      type: "nightmare_fear_committed",
      payload: { actorId, day, targetId },
      audience: Object.freeze([actorId]),
    });
  },
};

/**
 * Unit tests for nightmare; Isolated nightmare state contract; native in-memory owner/frame/readers, no assembled game cycle.
 * Inputs are existing in-memory fixtures, original callback controls and explicit
 * invalid mutations. Original literal expectations, identity snapshots and
 * rejection assertions supply the oracle; none are regenerated during relocation.
 * Test-owned mocks/components exercise this boundary without a model or physical
 * transport. Support files, fixture bytes, policy and state behavior are retained.
 */
import { describe, expect, test } from "bun:test";
import type { RoleComponent } from "../../../../src/core/domain/components/role";
import { Camp } from "../../../../src/core/domain/identity";
import {
  freshNightmareShadowState,
  getNightmareShadowState,
} from "../../../../src/game/mechanisms/roles/nightmare_shadow/state";
function role(state: unknown): RoleComponent {
  return {
    role: "nightmare",
    camp: Camp.Wolf,
    privateState: { nightmareShadow: state },
  } as unknown as RoleComponent;
}
describe("nightmare shadow private state", () => {
  test("fresh states are independent and use explicit optional/standard defaults", () => {
    const a = freshNightmareShadowState(),
      b = freshNightmareShadowState();
    expect(a.fearActionPolicy).toBe("optional");
    expect(a.wolfActionPolicy).toBe("standard");
    expect(a.packReady).toBe(false);
    expect(a.lastDay).toBeNull();
    expect(a.lastTarget).toBeNull();
    a.history.push({ day: 1, targetId: 2 });
    a.lastDay = 1;
    a.lastTarget = 2;
    a.packReady = true;
    expect(b.history).toEqual([]);
    expect(getNightmareShadowState(role(a))).toBe(a);
  });
  for (const fear of ["optional", "required_when_legal"] as const)
    for (const wolf of ["standard", "no_blast_no_self_knife"] as const)
      test(fear + "/" + wolf, () => {
        const state = freshNightmareShadowState(fear, wolf);
        expect(getNightmareShadowState(role(state))).toBe(state);
      });
  for (const [key, value] of [
    ["policy", "unknown"],
    ["fearActionPolicy", "random"],
    ["wolfActionPolicy", "random"],
    ["packReady", 1],
    ["lastDay", -1],
    ["lastDay", Number.NaN],
    ["lastDay", 1.5],
    ["lastTarget", "2"],
    ["history", {}],
  ] as const)
    test("reject invalid " + key + "/" + String(value), () => {
      const state = { ...freshNightmareShadowState(), [key]: value };
      expect(getNightmareShadowState(role(state))).toBeUndefined();
    });
  test("reject state getters without evaluating them", () => {
    let reads = 0;
    const state = freshNightmareShadowState();
    Object.defineProperty(state, "packReady", {
      get() {
        reads++;
        return false;
      },
    });
    expect(getNightmareShadowState(role(state))).toBeUndefined();
    expect(reads).toBe(0);
  });
  test("reject proxy state and proxy role without reading traps", () => {
    let reads = 0;
    const handler = {
      get() {
        reads++;
        throw new Error("must not read");
      },
    };
    expect(
      getNightmareShadowState(role(new Proxy(freshNightmareShadowState(), handler))),
    ).toBeUndefined();
    expect(
      getNightmareShadowState(new Proxy(role(freshNightmareShadowState()), handler)),
    ).toBeUndefined();
    expect(reads).toBe(0);
  });
  test("reject wrong role or camp", () => {
    const r = role(freshNightmareShadowState());
    expect(getNightmareShadowState({ ...r, camp: Camp.Good })).toBeUndefined();
    expect(getNightmareShadowState({ ...r, role: "wolf" } as RoleComponent)).toBeUndefined();
  });
});

test("nightmare rejects revoked history and inconsistent progression", () => {
  const revoked = Proxy.revocable([], {});
  const state = freshNightmareShadowState();
  state.history = revoked.proxy;
  revoked.revoke();
  expect(() => getNightmareShadowState(role(state))).not.toThrow();
  expect(getNightmareShadowState(role(state))).toBeUndefined();
  for (const value of [
    { packReady: true, lastDay: 1, lastTarget: null, history: [{ day: 1, targetId: 2 }] },
    { packReady: false, lastDay: 1, lastTarget: 2, history: [{ day: 1, targetId: 2 }] },
    { packReady: true, lastDay: null, lastTarget: null, history: [] },
    { packReady: true, lastDay: 1, lastTarget: 2, history: [] },
    {
      packReady: true,
      lastDay: 1,
      lastTarget: 2,
      history: [
        { day: 1, targetId: 2 },
        { day: 1, targetId: 2 },
      ],
    },
  ])
    expect(
      getNightmareShadowState(role({ ...freshNightmareShadowState(), ...value })),
    ).toBeUndefined();
});

/**
 * 单元测试验证 nightmare 的独立 frame.test 契约。输入为既有内存 fixture、原回调控制和明确非法
 * 修改；原字面预期、身份快照及拒绝断言是预期，不在迁移中重新生成。仅调用原生内存
 * owner／frame／reader，测试自有 mock／组件不运行完整对局、模型或真实传输，support／fixture 字节及政策状态不变。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { COMPONENT } from "../../../../src/core/domain/components/names";

import type { RoleComponent } from "../../../../src/core/domain/components/role";
import { Camp } from "../../../../src/core/domain/identity";
import type { World } from "../../../../src/core/domain/world";
import {
  freshNightmareShadowState,
  nightmareFearTargets,
} from "../../../../src/game/mechanisms/roles/nightmare_shadow/state";
import {
  installNightmareBoard,
  beginNightmareNight,
  commitNightmareFear,
  nightmareFearBlocks,
  nightmareKnifeBlocked,
  nightmarePackReady,
  assertNightmareRosterCurrent,
} from "../../../../src/game/mechanisms/roles/nightmare_shadow/night_frame";
function fixture(required = false, constructorLocation?: "own" | "inherited") {
  const state = freshNightmareShadowState(required ? "required_when_legal" : "optional");
  const roles = new Map<number, RoleComponent>([
    [
      1,
      {
        role: "nightmare",
        camp: Camp.Wolf,
        privateState: { nightmareShadow: state },
      } as unknown as RoleComponent,
    ],
    [2, { role: "wolf", camp: Camp.Wolf, privateState: {} } as RoleComponent],
    [3, { role: "seer", camp: Camp.Good, privateState: {} } as RoleComponent],
    [4, { role: "hunter", camp: Camp.Good, privateState: {} } as RoleComponent],
  ]);
  const lives = new Map([...roles.keys()].map((id) => [id, createAliveComponent()]));
  const world = {
    entityIds: () => [...roles.keys()],
    getAliveEntityIds: () => [...lives].filter(([, life]) => life.alive).map(([id]) => id),
    getComponent: (id: number, kind: unknown) =>
      kind === COMPONENT.Role
        ? roles.get(id)
        : kind === COMPONENT.Alive
          ? lives.get(id)
          : undefined,
  } as unknown as World;
  if (constructorLocation) {
    const owner =
      constructorLocation === "own" ? state.history : (Object.create(Array.prototype) as object);
    Object.defineProperty(owner, "constructor", {
      get() {
        throw new Error("nightmare_frame_constructor_getter_executed");
      },
    });
    if (constructorLocation === "inherited") Object.setPrototypeOf(state.history, owner);
  }
  installNightmareBoard(world);
  return { world, state, roles, lives };
}
test("first fear precedes pack knowledge and blocks all knife but not identity", () => {
  const { world, state } = fixture();
